const legacyNames=new Map(legacyResourceNames.map(([name],index)=>['R'+String(index+1).padStart(2,'0'),name]));
export function migrateMuseumCase(state){
 const isLegacyMuseum=state.museum?.name==='云川历史工艺博物馆'&&state.museum.city==='云川市（虚构）';
 const oldResources=state.resources||[];
 const retained=oldResources.filter(item=>legacyNames.get(item.id)!==item.name);
 const removed=new Set(oldResources.filter(item=>!retained.includes(item)).map(item=>item.id));
 if(!isLegacyMuseum&&!removed.size)return false;
 if(isLegacyMuseum){
  state.museum=structuredClone(museum);
  const existing=new Set(retained.map(item=>item.id));
  retained.push(...structuredClone(resources.filter(item=>!existing.has(item.id))));
 }
 state.resources=retained.map(item=>item.memberIds?.some(id=>removed.has(id))?{...item,memberIds:item.memberIds.filter(id=>!removed.has(id))}:item);
 return true;
}
